        judges(15, 6, "Judges", 14, 15, "The burning of Samson's wife and father is the consequence of the Philistines' coercion during the riddle episode."),
        judges(16, 17, "Judges", 13, 5, "Samson's disclosure that no razor has touched his head recalls the Nazirite calling announced before his birth."),
