        Entry(bookName: "Proverbs", chapterNumber: 20, sourceVerse: 16, targetBookName: "Proverbs", targetChapterNumber: 27, targetVerse: 13, relationshipDescription: "Proverbs 27 repeats the warning to take a pledge from one who guarantees a stranger's debt."),
        Entry(bookName: "Proverbs", chapterNumber: 20, sourceVerse: 19, targetBookName: "Proverbs", targetChapterNumber: 11, targetVerse: 13, relationshipDescription: "Proverbs 20 repeats the contrast between the gossip who reveals secrets and the faithful person who keeps confidence."),
        Entry(bookName: "Proverbs", chapterNumber: 20, sourceVerse: 20, targetBookName: "Exodus", targetChapterNumber: 21, targetVerse: 17, relationshipDescription: "Proverbs warns that cursing parents brings extinction, applying the covenant law's capital penalty for this offense as a wisdom warning."),
        Entry(bookName: "Proverbs", chapterNumber: 21, sourceVerse: 9, targetBookName: "Proverbs", targetChapterNumber: 25, targetVerse: 24, relationshipDescription: "Proverbs 25 repeats the saying that solitude on a roof corner is better than sharing a home with a quarrelsome spouse."),
        Entry(bookName: "Proverbs", chapterNumber: 22, sourceVerse: 3, targetBookName: "Proverbs", targetChapterNumber: 27, targetVerse: 12, relationshipDescription: "Proverbs 27 repeats the prudent person's foresight in seeing danger and taking refuge while the naïve suffer for going on."),
        Entry(bookName: "Proverbs", chapterNumber: 22, sourceVerse: 13, targetBookName: "Proverbs", targetChapterNumber: 26, targetVerse: 13, relationshipDescription: "Proverbs 26 expands the sluggard's lion-in-the-street excuse into a portrait of paralysis, delay, and self-deception."),
        Entry(bookName: "Proverbs", chapterNumber: 23, sourceVerse: 18, targetBookName: "Proverbs", targetChapterNumber: 24, targetVerse: 14, relationshipDescription: "Proverbs 24 applies Proverbs 23's assurance of a future hope that will not be cut off to the pursuit of wisdom."),
        Entry(bookName: "Proverbs", chapterNumber: 24, sourceVerse: 6, targetBookName: "Proverbs", targetChapterNumber: 11, targetVerse: 14, relationshipDescription: "Proverbs 24 repeats that success and safety depend on wise guidance and an abundance of counselors."),
        Entry(bookName: "Proverbs", chapterNumber: 24, sourceVerse: 23, targetBookName: "Proverbs", targetChapterNumber: 28, targetVerse: 21, relationshipDescription: "Proverbs 28 repeats the warning that showing partiality is wrong and adds how easily it can corrupt judgment."),
        Entry(bookName: "Proverbs", chapterNumber: 25, sourceVerse: 21, targetBookName: "Romans", targetChapterNumber: 12, targetVerse: 20, relationshipDescription: "Paul quotes Proverbs' command to feed and give drink to an enemy as the Christian alternative to personal vengeance."),
        Entry(bookName: "Proverbs", chapterNumber: 26, sourceVerse: 11, targetBookName: "2 Peter", targetChapterNumber: 2, targetVerse: 22, relationshipDescription: "Peter quotes Proverbs' image of a dog returning to vomit to describe false teachers who return to corruption after knowing the way of righteousness."),
        Entry(bookName: "Ecclesiastes", chapterNumber: 1, sourceVerse: 2, targetBookName: "Ecclesiastes", targetChapterNumber: 12, targetVerse: 8, relationshipDescription: "Ecclesiastes 12 repeats the opening verdict that everything is vapor, framing the book's closing reflection with its governing question."),
        Entry(bookName: "Ecclesiastes", chapterNumber: 1, sourceVerse: 3, targetBookName: "Ecclesiastes", targetChapterNumber: 2, targetVerse: 22, relationshipDescription: "Ecclesiastes 2 develops the opening question about lasting gain from labor by asking what a person truly receives from all anxious toil."),
        Entry(bookName: "Ecclesiastes", chapterNumber: 1, sourceVerse: 3, targetBookName: "Ecclesiastes", targetChapterNumber: 5, targetVerse: 18, relationshipDescription: "Ecclesiastes 5 answers the question of gain under the sun by commending thankful enjoyment of work, food, and drink as God's gift."),
        Entry(bookName: "Ecclesiastes", chapterNumber: 1, sourceVerse: 14, targetBookName: "Ecclesiastes", targetChapterNumber: 2, targetVerse: 11, relationshipDescription: "Ecclesiastes 2 applies the opening verdict that all is vapor and chasing the wind to the Teacher's achievements and pleasures."),
        Entry(bookName: "Ecclesiastes", chapterNumber: 1, sourceVerse: 14, targetBookName: "Ecclesiastes", targetChapterNumber: 2, targetVerse: 17, relationshipDescription: "Ecclesiastes 2 applies the opening verdict of vanity to the Teacher's despair over life and work under the sun."),
        Entry(bookName: "Ecclesiastes", chapterNumber: 1, sourceVerse: 14, targetBookName: "Ecclesiastes", targetChapterNumber: 2, targetVerse: 26, relationshipDescription: "Ecclesiastes 2 applies the opening verdict of chasing the wind to the sinner's futile accumulation of wealth for another."),
        Entry(bookName: "Ecclesiastes", chapterNumber: 5, sourceVerse: 19, targetBookName: "Ecclesiastes", targetChapterNumber: 6, targetVerse: 2, relationshipDescription: "Ecclesiastes 6 gives the dark counterpart to the gift praised in Ecclesiastes 5: wealth without God's grant of enjoyment becomes a grievous evil."),
        Entry(bookName: "Ecclesiastes", chapterNumber: 10, sourceVerse: 8, targetBookName: "Proverbs", targetChapterNumber: 26, targetVerse: 27, relationshipDescription: "Proverbs repeats Ecclesiastes' warning that a person can fall into the pit he digs or be harmed by the stone he rolls."),
        Entry(bookName: "Song of Solomon", chapterNumber: 1, sourceVerse: 8, targetBookName: "Song of Solomon", targetChapterNumber: 6, targetVerse: 1, relationshipDescription: "The daughters' question in Song 6 about where the beloved has gone develops the earlier search for where he pastures his flock."),
        Entry(bookName: "Song of Solomon", chapterNumber: 1, sourceVerse: 8, targetBookName: "Song of Solomon", targetChapterNumber: 5, targetVerse: 9, relationshipDescription: "Song 5 addresses the woman as the fairest among women while asking why her beloved is special, echoing the title used in the earlier search dialogue."),
        Entry(bookName: "Song of Solomon", chapterNumber: 1, sourceVerse: 15, targetBookName: "Song of Solomon", targetChapterNumber: 4, targetVerse: 1, relationshipDescription: "The beloved repeats his praise of her beauty and dove-like eyes in Song 4, expanding the earlier declaration into a fuller love poem."),
        Entry(bookName: "Song of Solomon", chapterNumber: 5, sourceVerse: 9, targetBookName: "Song of Solomon", targetChapterNumber: 6, targetVerse: 1, relationshipDescription: "After the daughters ask why her beloved is exceptional, they ask where he has gone so they can join her search, advancing the dialogue of longing."),
        Entry(bookName: "Song of Solomon", chapterNumber: 2, sourceVerse: 7, targetBookName: "Song of Solomon", targetChapterNumber: 3, targetVerse: 5, relationshipDescription: "Song 3 repeats the charge not to awaken love before its proper time, preserving the poem's refrain on love's fitting season."),
        Entry(bookName: "Song of Solomon", chapterNumber: 2, sourceVerse: 7, targetBookName: "Song of Solomon", targetChapterNumber: 8, targetVerse: 4, relationshipDescription: "Song 8 repeats the charge not to awaken love before its proper time as the poem returns to its central refrain near the close."),
        Entry(bookName: "Song of Solomon", chapterNumber: 2, sourceVerse: 16, targetBookName: "Song of Solomon", targetChapterNumber: 6, targetVerse: 3, relationshipDescription: "Song 6 repeats the lovers' mutual-belonging confession, reversing its order to affirm their renewed intimacy."),
        Entry(bookName: "Song of Solomon", chapterNumber: 2, sourceVerse: 17, targetBookName: "Song of Solomon", targetChapterNumber: 4, targetVerse: 6, relationshipDescription: "Song 4 reuses the daybreak-and-fleeing-shadows setting from Song 2 as the beloved speaks of going to the mountain of myrrh."),
        Entry(bookName: "Song of Solomon", chapterNumber: 2, sourceVerse: 17, targetBookName: "Song of Solomon", targetChapterNumber: 8, targetVerse: 14, relationshipDescription: "The closing invitation repeats Song 2's call for the beloved to be like a gazelle on the mountains, turning it into the poem's final longing."),
        Entry(bookName: "Song of Solomon", chapterNumber: 4, sourceVerse: 1, targetBookName: "Song of Solomon", targetChapterNumber: 6, targetVerse: 5, relationshipDescription: "Song 6 repeats the beloved's dove-like eyes and says their gaze overwhelms him, continuing the sequence of praises from Song 4."),
        Entry(bookName: "Song of Solomon", chapterNumber: 4, sourceVerse: 2, targetBookName: "Song of Solomon", targetChapterNumber: 6, targetVerse: 6, relationshipDescription: "Song 6 repeats the image of her teeth as a washed flock, reaffirming the beloved's physical praise."),
        Entry(bookName: "Song of Solomon", chapterNumber: 4, sourceVerse: 3, targetBookName: "Song of Solomon", targetChapterNumber: 6, targetVerse: 7, relationshipDescription: "Song 6 repeats the image of her temples like a pomegranate behind her veil, continuing the beloved's description from Song 4.")
    ]

    private nonisolated static let entriesPart48: [Entry] = [
        Entry(bookName: "Isaiah", chapterNumber: 1, sourceVerse: 9, targetBookName: "Romans", targetChapterNumber: 9, targetVerse: 29, relationshipDescription: "Paul quotes Isaiah's remnant image to show that Israel's survival rests on the Lord's preserving mercy, not human descent or effort."),
        Entry(bookName: "Isaiah", chapterNumber: 2, sourceVerse: 2, targetBookName: "Micah", targetChapterNumber: 4, targetVerse: 1, relationshipDescription: "Micah repeats Isaiah's vision of the Lord's mountain raised above all others and the nations streaming to receive God's instruction."),
        Entry(bookName: "Isaiah", chapterNumber: 2, sourceVerse: 4, targetBookName: "Micah", targetChapterNumber: 4, targetVerse: 3, relationshipDescription: "Micah repeats Isaiah's vision of God judging nations so weapons become tools of cultivation and war ceases."),
        Entry(bookName: "Isaiah", chapterNumber: 2, sourceVerse: 11, targetBookName: "Isaiah", targetChapterNumber: 5, targetVerse: 15, relationshipDescription: "Isaiah 5 develops the warning that human pride will be brought low by declaring that people are humbled and the Lord alone exalted in judgment."),
        Entry(bookName: "Isaiah", chapterNumber: 3, sourceVerse: 9, targetBookName: "Genesis", targetChapterNumber: 13, targetVerse: 13, relationshipDescription: "Isaiah compares Judah's public sin to Sodom's notorious wickedness, invoking the city whose rebellion brought divine judgment."),
        Entry(bookName: "Isaiah", chapterNumber: 5, sourceVerse: 25, targetBookName: "Isaiah", targetChapterNumber: 10, targetVerse: 4, relationshipDescription: "Isaiah 10 repeats the refrain that the Lord's anger remains and his hand is still stretched out, tying later judgment to the same unresolved indictment."),
        Entry(bookName: "Isaiah", chapterNumber: 5, sourceVerse: 25, targetBookName: "Isaiah", targetChapterNumber: 9, targetVerse: 21, relationshipDescription: "Isaiah 9 repeats the refrain that the Lord's anger remains and his hand is still stretched out, joining the judgment oracles into a single sequence."),
        Entry(bookName: "Isaiah", chapterNumber: 5, sourceVerse: 25, targetBookName: "Isaiah", targetChapterNumber: 9, targetVerse: 17, relationshipDescription: "Isaiah 9 repeats the refrain that the Lord's anger remains and his hand is still stretched out, joining the judgment oracles into a single sequence."),
        Entry(bookName: "Isaiah", chapterNumber: 6, sourceVerse: 9, targetBookName: "Acts", targetChapterNumber: 28, targetVerse: 26, relationshipDescription: "Paul quotes Isaiah's commission about hearing without understanding to explain the rejection of his gospel proclamation and its turn to the Gentiles."),
        Entry(bookName: "Isaiah", chapterNumber: 6, sourceVerse: 9, targetBookName: "John", targetChapterNumber: 12, targetVerse: 40, relationshipDescription: "John applies Isaiah's hardening commission to explain why many who saw Jesus' signs still did not believe in him."),
        Entry(bookName: "Isaiah", chapterNumber: 6, sourceVerse: 10, targetBookName: "John", targetChapterNumber: 12, targetVerse: 39, relationshipDescription: "John cites Isaiah's hardening commission as the reason many could not believe after Jesus' signs, linking their unbelief to the prophet's vision."),
        Entry(bookName: "Isaiah", chapterNumber: 7, sourceVerse: 14, targetBookName: "Matthew", targetChapterNumber: 1, targetVerse: 22, relationshipDescription: "Matthew introduces Jesus' birth as the fulfillment of Isaiah's Immanuel sign before quoting the prophecy."),
        Entry(bookName: "Isaiah", chapterNumber: 8, sourceVerse: 18, targetBookName: "Hebrews", targetChapterNumber: 2, targetVerse: 13, relationshipDescription: "Hebrews applies Isaiah's declaration about himself and the children God gave him to Jesus and the children he brings before God."),
        Entry(bookName: "Isaiah", chapterNumber: 9, sourceVerse: 1, targetBookName: "Matthew", targetChapterNumber: 4, targetVerse: 14, relationshipDescription: "Matthew presents Jesus' move to Galilee as the fulfillment of Isaiah's promise that light would dawn on Zebulun and Naphtali."),
        Entry(bookName: "Isaiah", chapterNumber: 10, sourceVerse: 22, targetBookName: "Romans", targetChapterNumber: 9, targetVerse: 27, relationshipDescription: "Paul quotes Isaiah's remnant warning to show that only a remnant of Israel will be saved despite Israel's vast number."),
        Entry(bookName: "Isaiah", chapterNumber: 11, sourceVerse: 10, targetBookName: "Romans", targetChapterNumber: 15, targetVerse: 12, relationshipDescription: "Paul quotes Isaiah's root of Jesse to ground the nations' hope in the Messiah and urge Jewish and Gentile believers to welcome one another."),
        Entry(bookName: "Isaiah", chapterNumber: 12, sourceVerse: 2, targetBookName: "Psalms", targetChapterNumber: 118, targetVerse: 14, relationshipDescription: "Psalm 118 repeats Isaiah's confession that the Lord is strength, song, and salvation, turning the prophet's song into thanksgiving for deliverance."),
        Entry(bookName: "Isaiah", chapterNumber: 13, sourceVerse: 6, targetBookName: "Joel", targetChapterNumber: 1, targetVerse: 15, relationshipDescription: "Joel repeats Isaiah's announcement that the day of the Lord brings destruction from the Almighty, applying the judgment formula to his own crisis."),
        Entry(bookName: "Isaiah", chapterNumber: 13, sourceVerse: 10, targetBookName: "Mark", targetChapterNumber: 13, targetVerse: 24, relationshipDescription: "Mark preserves Jesus' use of Isaiah's darkened heavenly lights to portray the cosmic judgment that follows the tribulation."),
        Entry(bookName: "Isaiah", chapterNumber: 13, sourceVerse: 13, targetBookName: "Haggai", targetChapterNumber: 2, targetVerse: 6, relationshipDescription: "Haggai develops Isaiah's image of the Lord shaking heaven and earth: Isaiah announces Babylon's downfall, while Haggai promises a future shaking of nations."),
        Entry(bookName: "Isaiah", chapterNumber: 13, sourceVerse: 13, targetBookName: "Haggai", targetChapterNumber: 2, targetVerse: 21, relationshipDescription: "Haggai reuses Isaiah's heaven-and-earth shaking imagery when promising to overthrow kingdoms, extending the judgment pattern beyond Babylon."),
        Entry(bookName: "Isaiah", chapterNumber: 13, sourceVerse: 17, targetBookName: "Daniel", targetChapterNumber: 5, targetVerse: 28, relationshipDescription: "Isaiah names the Medes as Babylon's attackers; Daniel records the Medes and Persians receiving Babylon's kingdom after Belshazzar's fall."),
        Entry(bookName: "Isaiah", chapterNumber: 13, sourceVerse: 17, targetBookName: "Jeremiah", targetChapterNumber: 51, targetVerse: 11, relationshipDescription: "Jeremiah repeats Isaiah's announcement that the Lord has stirred up the Medes against Babylon, confirming the same agent of its judgment."),
        Entry(bookName: "Isaiah", chapterNumber: 13, sourceVerse: 19, targetBookName: "Jeremiah", targetChapterNumber: 50, targetVerse: 40, relationshipDescription: "Jeremiah repeats Isaiah's comparison of Babylon's fate to Sodom and Gomorrah, declaring that its overthrow will leave it uninhabited."),
        Entry(bookName: "Isaiah", chapterNumber: 14, sourceVerse: 28, targetBookName: "2 Kings", targetChapterNumber: 16, targetVerse: 20, relationshipDescription: "Isaiah dates this oracle to the year King Ahaz died, the death recorded in Kings at the close of his reign."),
        Entry(bookName: "Isaiah", chapterNumber: 15, sourceVerse: 5, targetBookName: "Jeremiah", targetChapterNumber: 48, targetVerse: 5, relationshipDescription: "Jeremiah's oracle over Moab repeats Isaiah's ascent of Luhith and the cry at Horonaim, extending the lament over Moab's ruin.")
        ,Entry(bookName: "Isaiah", chapterNumber: 16, sourceVerse: 9, targetBookName: "Jeremiah", targetChapterNumber: 48, targetVerse: 32, relationshipDescription: "Jeremiah repeats Isaiah's lament for Sibmah's vine and its lost summer fruit, carrying forward the mourning over Moab's devastated vineyards.")
        ,Entry(bookName: "Isaiah", chapterNumber: 17, sourceVerse: 1, targetBookName: "Amos", targetChapterNumber: 1, targetVerse: 3, relationshipDescription: "Both prophets pronounce the Lord's judgment on Damascus: Amos indicts its brutality, while Isaiah foresees the city's complete ruin.")
        ,Entry(bookName: "Isaiah", chapterNumber: 17, sourceVerse: 1, targetBookName: "Zechariah", targetChapterNumber: 9, targetVerse: 1, relationshipDescription: "Zechariah's burden against Damascus continues the prophetic witness that this leading Aramean city lies under the Lord's judgment.")
        ,Entry(bookName: "Isaiah", chapterNumber: 17, sourceVerse: 3, targetBookName: "Isaiah", targetChapterNumber: 8, targetVerse: 4, relationshipDescription: "Isaiah 17 develops the earlier warning that Assyria would carry off Damascus's wealth and Samaria's spoil by announcing the collapse of both Aram and Ephraim.")
        ,Entry(bookName: "Isaiah", chapterNumber: 17, sourceVerse: 6, targetBookName: "Isaiah", targetChapterNumber: 24, targetVerse: 13, relationshipDescription: "Isaiah 24 repeats the olive-beating and gleaning image from Isaiah 17 to portray the few survivors left after worldwide judgment.")
        ,Entry(bookName: "Isaiah", chapterNumber: 19, sourceVerse: 3, targetBookName: "Isaiah", targetChapterNumber: 8, targetVerse: 19, relationshipDescription: "Isaiah contrasts Judah's forbidden consultation of mediums with Egypt's desperate turn to idols and spiritists when the Lord confounds its counsel.")
        ,Entry(bookName: "Isaiah", chapterNumber: 19, sourceVerse: 4, targetBookName: "Isaiah", targetChapterNumber: 20, targetVerse: 4, relationshipDescription: "Isaiah 20 dramatizes the harsh rule foretold for Egypt in Isaiah 19 by depicting Egyptians led away captive by Assyria.")
        ,Entry(bookName: "Isaiah", chapterNumber: 19, sourceVerse: 13, targetBookName: "Ezekiel", targetChapterNumber: 30, targetVerse: 13, relationshipDescription: "Both Egyptian judgment oracles name Memphis (Noph): Isaiah condemns its misleading leaders, while Ezekiel announces the end of its idols and princes.")
        ,Entry(bookName: "Isaiah", chapterNumber: 19, sourceVerse: 23, targetBookName: "Isaiah", targetChapterNumber: 11, targetVerse: 16, relationshipDescription: "Isaiah expands the highway for the Assyrian remnant into an eschatological road joining Egypt, Assyria, and Israel in shared worship of the Lord.")
        ,Entry(bookName: "Isaiah", chapterNumber: 21, sourceVerse: 2, targetBookName: "Jeremiah", targetChapterNumber: 49, targetVerse: 34, relationshipDescription: "Isaiah names Elam among the forces advancing against Babylon; Jeremiah later delivers a distinct oracle of judgment and eventual restoration for Elam itself.")
        ,Entry(bookName: "Isaiah", chapterNumber: 21, sourceVerse: 9, targetBookName: "Revelation", targetChapterNumber: 18, targetVerse: 2, relationshipDescription: "Revelation directly repeats Isaiah's cry, 'Fallen, fallen is Babylon,' to announce the collapse of end-time Babylon.")
        ,Entry(bookName: "Isaiah", chapterNumber: 21, sourceVerse: 9, targetBookName: "Revelation", targetChapterNumber: 14, targetVerse: 8, relationshipDescription: "Revelation directly repeats Isaiah's announcement of fallen Babylon as a warning that the power corrupting the nations will be judged.")
        ,Entry(bookName: "Isaiah", chapterNumber: 21, sourceVerse: 16, targetBookName: "Isaiah", targetChapterNumber: 60, targetVerse: 7, relationshipDescription: "Isaiah contrasts Kedar's approaching loss of glory with the later restoration vision in which Kedar's flocks are welcomed as offerings on the Lord's altar.")
        ,Entry(bookName: "Isaiah", chapterNumber: 22, sourceVerse: 13, targetBookName: "1 Corinthians", targetChapterNumber: 15, targetVerse: 32, relationshipDescription: "Paul quotes Isaiah's fatalistic feast slogan to reject a life without resurrection hope: if the dead are not raised, eating and drinking is all that remains.")
    ]

    private nonisolated static let entriesPart49: [Entry] = [
        Entry(bookName: "Isaiah", chapterNumber: 23, sourceVerse: 1, targetBookName: "Joel", targetChapterNumber: 3, targetVerse: 4, relationshipDescription: "Joel names Tyre and Sidon among the nations answerable for harming God's people, extending Isaiah's oracle of judgment against Tyre."),
        Entry(bookName: "Isaiah", chapterNumber: 24, sourceVerse: 17, targetBookName: "Jeremiah", targetChapterNumber: 48, targetVerse: 43, relationshipDescription: "Jeremiah repeats Isaiah's sequence of terror, pit, and snare in his oracle that Moab cannot escape the Lord's judgment."),
        Entry(bookName: "Isaiah", chapterNumber: 25, sourceVerse: 8, targetBookName: "1 Corinthians", targetChapterNumber: 15, targetVerse: 54, relationshipDescription: "Paul quotes Isaiah's promise that death will be swallowed up to celebrate the resurrection victory secured when believers receive imperishable life."),
        Entry(bookName: "Isaiah", chapterNumber: 27, sourceVerse: 13, targetBookName: "Isaiah", targetChapterNumber: 19, targetVerse: 23, relationshipDescription: "Isaiah develops the highway between Egypt and Assyria into a worldwide summons: exiles return to worship the Lord in Jerusalem alongside those former enemies."),
        Entry(bookName: "Isaiah", chapterNumber: 28, sourceVerse: 11, targetBookName: "1 Corinthians", targetChapterNumber: 14, targetVerse: 21, relationshipDescription: "Paul quotes Isaiah's foreign-tongue warning to explain that tongues function as a sign for unbelievers rather than as the church's primary means of edification."),
        Entry(bookName: "Isaiah", chapterNumber: 28, sourceVerse: 16, targetBookName: "1 Peter", targetChapterNumber: 2, targetVerse: 6, relationshipDescription: "Peter identifies Jesus as Isaiah's chosen cornerstone, assuring believers that trust in him will not lead to shame."),
        Entry(bookName: "Isaiah", chapterNumber: 28, sourceVerse: 16, targetBookName: "Romans", targetChapterNumber: 10, targetVerse: 11, relationshipDescription: "Paul cites Isaiah's promise that whoever believes will not be put to shame to affirm that salvation is equally open to everyone who calls on the Lord."),
        Entry(bookName: "Isaiah", chapterNumber: 28, sourceVerse: 16, targetBookName: "Romans", targetChapterNumber: 9, targetVerse: 33, relationshipDescription: "Paul combines Isaiah's cornerstone promise with Isaiah's stone of stumbling to explain why faith in Christ saves while reliance on the law leads many in Israel to stumble."),
        Entry(bookName: "Isaiah", chapterNumber: 29, sourceVerse: 14, targetBookName: "1 Corinthians", targetChapterNumber: 1, targetVerse: 19, relationshipDescription: "Paul quotes Isaiah's promise to destroy the wise people's wisdom to show that God overturns worldly wisdom through the message of the cross."),
        Entry(bookName: "Isaiah", chapterNumber: 30, sourceVerse: 4, targetBookName: "Isaiah", targetChapterNumber: 19, targetVerse: 11, relationshipDescription: "Isaiah's mention of Judah's envoys at Zoan exposes their futile reliance on Egypt, whose counselors Isaiah had already condemned as foolish."),
        Entry(bookName: "Isaiah", chapterNumber: 30, sourceVerse: 33, targetBookName: "Jeremiah", targetChapterNumber: 19, targetVerse: 6, relationshipDescription: "Jeremiah's judgment at Topheth draws on the same notorious site Isaiah names as prepared for the king, extending its association with divine punishment."),
        Entry(bookName: "Isaiah", chapterNumber: 31, sourceVerse: 3, targetBookName: "Isaiah", targetChapterNumber: 30, targetVerse: 7, relationshipDescription: "Isaiah restates the warning against trusting Egypt: its help is empty because Egypt is human rather than God, not the saving power Judah seeks."),
        Entry(bookName: "Isaiah", chapterNumber: 32, sourceVerse: 15, targetBookName: "Isaiah", targetChapterNumber: 29, targetVerse: 17, relationshipDescription: "Isaiah returns to the promised reversal of wilderness and fruitful field, now identifying the outpoured Spirit as the source of that restoration."),
        Entry(bookName: "Isaiah", chapterNumber: 34, sourceVerse: 6, targetBookName: "Isaiah", targetChapterNumber: 63, targetVerse: 1, relationshipDescription: "Isaiah's judgment at Bozrah is developed in the divine warrior vision from Bozrah, where the Lord's bloodstained garments reveal his execution of wrath."),
        Entry(bookName: "Isaiah", chapterNumber: 34, sourceVerse: 14, targetBookName: "Isaiah", targetChapterNumber: 13, targetVerse: 21, relationshipDescription: "Isaiah uses the same desert-creature imagery first applied to Babylon to portray Edom as a permanently desolate place after judgment."),
        Entry(bookName: "Isaiah", chapterNumber: 35, sourceVerse: 2, targetBookName: "Isaiah", targetChapterNumber: 60, targetVerse: 13, relationshipDescription: "Isaiah's restoration imagery links Lebanon's splendor with the Lord's glory: the transformed land and the beautified sanctuary both display his majesty."),
        Entry(bookName: "Isaiah", chapterNumber: 39, sourceVerse: 6, targetBookName: "2 Kings", targetChapterNumber: 24, targetVerse: 13, relationshipDescription: "Kings records Babylon carrying off the temple treasures, fulfilling Isaiah's warning that Hezekiah's storehouses would be taken away."),
        Entry(bookName: "Isaiah", chapterNumber: 40, sourceVerse: 3, targetBookName: "John", targetChapterNumber: 1, targetVerse: 23, relationshipDescription: "John the Baptist identifies himself as Isaiah's wilderness voice, preparing the way for the Lord by pointing to Jesus."),
        Entry(bookName: "Isaiah", chapterNumber: 40, sourceVerse: 3, targetBookName: "Luke", targetChapterNumber: 3, targetVerse: 4, relationshipDescription: "Luke applies Isaiah's wilderness proclamation to John the Baptist's ministry of preparing people for the Lord's saving arrival."),
        Entry(bookName: "Isaiah", chapterNumber: 40, sourceVerse: 6, targetBookName: "1 Peter", targetChapterNumber: 1, targetVerse: 24, relationshipDescription: "Peter quotes Isaiah's contrast between fading grass and God's enduring word to affirm the permanence of the gospel by which believers were born again."),
        Entry(bookName: "Isaiah", chapterNumber: 40, sourceVerse: 13, targetBookName: "1 Corinthians", targetChapterNumber: 2, targetVerse: 16, relationshipDescription: "Paul quotes Isaiah's question about knowing the Lord's mind, then declares that believers have the mind of Christ through the Spirit."),
        Entry(bookName: "Isaiah", chapterNumber: 40, sourceVerse: 13, targetBookName: "Romans", targetChapterNumber: 11, targetVerse: 34, relationshipDescription: "Paul quotes Isaiah's question about the Lord's mind and counsel to praise the unsearchable wisdom governing God's mercy toward Jew and Gentile."),
        Entry(bookName: "Isaiah", chapterNumber: 41, sourceVerse: 27, targetBookName: "Isaiah", targetChapterNumber: 52, targetVerse: 7, relationshipDescription: "Isaiah develops the announcement to Zion into the later image of the herald whose good news proclaims Zion's God reigns."),
        Entry(bookName: "Isaiah", chapterNumber: 41, sourceVerse: 27, targetBookName: "Nahum", targetChapterNumber: 1, targetVerse: 15, relationshipDescription: "Nahum reuses Isaiah's good-news herald imagery to announce Judah's relief after the downfall of its oppressor, Assyria."),
        Entry(bookName: "Isaiah", chapterNumber: 42, sourceVerse: 1, targetBookName: "Matthew", targetChapterNumber: 12, targetVerse: 17, relationshipDescription: "Matthew introduces Jesus' healing ministry as the fulfillment of Isaiah's servant song before quoting the passage about the Spirit-anointed servant."),
        Entry(bookName: "Isaiah", chapterNumber: 43, sourceVerse: 16, targetBookName: "Psalms", targetChapterNumber: 77, targetVerse: 19, relationshipDescription: "Both recall the Lord making a path through the sea at the exodus; Isaiah invokes that deliverance to promise a new act of salvation for Israel."),
        Entry(bookName: "Isaiah", chapterNumber: 43, sourceVerse: 25, targetBookName: "Isaiah", targetChapterNumber: 37, targetVerse: 35, relationshipDescription: "Isaiah links the Lord's forgiveness and Jerusalem's rescue to his own name and purposes rather than to any merit in his people."),
        Entry(bookName: "Isaiah", chapterNumber: 44, sourceVerse: 23, targetBookName: "Isaiah", targetChapterNumber: 49, targetVerse: 13, relationshipDescription: "Isaiah repeats the summons for heaven and earth to sing because the Lord has redeemed Jacob and displayed his glory in restoring Zion."),
        Entry(bookName: "Isaiah", chapterNumber: 44, sourceVerse: 28, targetBookName: "Isaiah", targetChapterNumber: 45, targetVerse: 1, relationshipDescription: "Isaiah immediately develops Cyrus's commission to rebuild Jerusalem by naming him the Lord's anointed instrument for subduing nations and freeing exiles."),
        Entry(bookName: "Isaiah", chapterNumber: 45, sourceVerse: 23, targetBookName: "Romans", targetChapterNumber: 14, targetVerse: 11, relationshipDescription: "Paul quotes Isaiah's universal confession before God to explain why every believer must answer to the Lord rather than judge a fellow servant."),
        Entry(bookName: "Isaiah", chapterNumber: 46, sourceVerse: 1, targetBookName: "Jeremiah", targetChapterNumber: 51, targetVerse: 44, relationshipDescription: "Jeremiah announces the punishment of Bel in Babylon, developing Isaiah's vision of Babylon's gods collapsing and being carried away."),
        Entry(bookName: "Isaiah", chapterNumber: 46, sourceVerse: 1, targetBookName: "Jeremiah", targetChapterNumber: 50, targetVerse: 2, relationshipDescription: "Jeremiah declares Bel and Merodach disgraced when Babylon falls, echoing Isaiah's announcement that its gods bow down powerless."),
        Entry(bookName: "Isaiah", chapterNumber: 48, sourceVerse: 13, targetBookName: "Psalms", targetChapterNumber: 102, targetVerse: 25, relationshipDescription: "Both praise the Lord as the one who founded the earth and made the heavens, grounding Isaiah's assurance in his enduring Creator-power."),
        Entry(bookName: "Isaiah", chapterNumber: 48, sourceVerse: 20, targetBookName: "Jeremiah", targetChapterNumber: 50, targetVerse: 8, relationshipDescription: "Jeremiah repeats Isaiah's command for God's people to flee Babylon, turning the prophetic call into an urgent summons before Babylon's fall."),
        Entry(bookName: "Isaiah", chapterNumber: 49, sourceVerse: 6, targetBookName: "Acts", targetChapterNumber: 13, targetVerse: 47, relationshipDescription: "Paul and Barnabas quote Isaiah's servant commission as their mandate to bring the Lord's salvation to the Gentiles."),
        Entry(bookName: "Isaiah", chapterNumber: 49, sourceVerse: 8, targetBookName: "2 Corinthians", targetChapterNumber: 6, targetVerse: 2, relationshipDescription: "Paul quotes Isaiah's promised time of favor and salvation to urge the Corinthians not to receive God's grace in vain, declaring that the decisive day has arrived."),
        Entry(bookName: "Isaiah", chapterNumber: 51, sourceVerse: 2, targetBookName: "Genesis", targetChapterNumber: 18, targetVerse: 11, relationshipDescription: "Isaiah points to Abraham and Sarah's impossible old-age beginning to assure Zion that the Lord can multiply one called ancestor into a great people."),
        Entry(bookName: "Isaiah", chapterNumber: 51, sourceVerse: 3, targetBookName: "Joel", targetChapterNumber: 2, targetVerse: 3, relationshipDescription: "Joel's Eden-like land turned wilderness intensifies Isaiah's promise that the Lord will reverse Zion's wilderness and make it like Eden."),
        Entry(bookName: "Isaiah", chapterNumber: 51, sourceVerse: 9, targetBookName: "Psalms", targetChapterNumber: 89, targetVerse: 10, relationshipDescription: "Both celebrate the Lord's defeat of Rahab as a display of his mastery over the sea; Isaiah invokes that ancient victory in a plea for renewed redemption."),
        Entry(bookName: "Isaiah", chapterNumber: 51, sourceVerse: 11, targetBookName: "Isaiah", targetChapterNumber: 35, targetVerse: 10, relationshipDescription: "Isaiah repeats the promise that the Lord's redeemed return to Zion with singing and everlasting joy, carrying the restoration vision into his appeal for comfort.")
    ]

    private nonisolated static let entriesPart50: [Entry] = [
        Entry(bookName: "Isaiah", chapterNumber: 52, sourceVerse: 5, targetBookName: "Romans", targetChapterNumber: 2, targetVerse: 24, relationshipDescription: "Paul cites Isaiah's lament that God's name is despised among the nations to indict Jewish hypocrisy that dishonors the God whose law they teach."),
        Entry(bookName: "Isaiah", chapterNumber: 52, sourceVerse: 7, targetBookName: "Romans", targetChapterNumber: 10, targetVerse: 15, relationshipDescription: "Paul quotes Isaiah's praise for beautiful feet bringing good news to describe the gospel messengers sent to proclaim Christ."),
        Entry(bookName: "Isaiah", chapterNumber: 52, sourceVerse: 11, targetBookName: "2 Corinthians", targetChapterNumber: 6, targetVerse: 17, relationshipDescription: "Paul applies Isaiah's call for departing exiles to touch no unclean thing as a summons for the church to separate from idolatry and uncleanness."),
        Entry(bookName: "Isaiah", chapterNumber: 52, sourceVerse: 15, targetBookName: "Romans", targetChapterNumber: 15, targetVerse: 21, relationshipDescription: "Paul quotes Isaiah's vision of nations seeing what they had not heard to explain his ambition to preach Christ where he was previously unknown."),
        Entry(bookName: "Isaiah", chapterNumber: 53, sourceVerse: 1, targetBookName: "John", targetChapterNumber: 12, targetVerse: 38, relationshipDescription: "John quotes Isaiah's question about the rejected report and revealed arm to explain why many who saw Jesus' signs still did not believe."),
        Entry(bookName: "Isaiah", chapterNumber: 53, sourceVerse: 1, targetBookName: "Romans", targetChapterNumber: 10, targetVerse: 16, relationshipDescription: "Paul quotes Isaiah's question about believing the report to explain Israel's widespread refusal of the gospel."),
        Entry(bookName: "Isaiah", chapterNumber: 53, sourceVerse: 7, targetBookName: "Acts", targetChapterNumber: 8, targetVerse: 32, relationshipDescription: "Philip begins with Isaiah's silent, slaughter-bound servant to proclaim Jesus to the Ethiopian official."),
        Entry(bookName: "Isaiah", chapterNumber: 53, sourceVerse: 9, targetBookName: "1 Peter", targetChapterNumber: 2, targetVerse: 22, relationshipDescription: "Peter cites the servant's sinlessness and lack of deceit as the pattern for believers enduring unjust suffering while following Christ."),
        Entry(bookName: "Isaiah", chapterNumber: 53, sourceVerse: 12, targetBookName: "Luke", targetChapterNumber: 22, targetVerse: 37, relationshipDescription: "Jesus identifies his coming arrest and death with Isaiah's servant being numbered among transgressors."),
        Entry(bookName: "Isaiah", chapterNumber: 53, sourceVerse: 1, targetBookName: "John", targetChapterNumber: 12, targetVerse: 37, relationshipDescription: "John introduces the unbelief after Jesus' many signs as the fulfillment of Isaiah's question about who believed the servant's report."),
        Entry(bookName: "Isaiah", chapterNumber: 53, sourceVerse: 5, targetBookName: "1 Peter", targetChapterNumber: 2, targetVerse: 24, relationshipDescription: "Peter applies Isaiah's wounded servant to Jesus bearing sins in his body on the cross so believers may die to sin and live righteously."),
        Entry(bookName: "Isaiah", chapterNumber: 54, sourceVerse: 1, targetBookName: "Galatians", targetChapterNumber: 4, targetVerse: 27, relationshipDescription: "Paul quotes Isaiah's promise to the barren woman to portray the children of the heavenly Jerusalem as the free heirs of God's promise."),
        Entry(bookName: "Isaiah", chapterNumber: 54, sourceVerse: 13, targetBookName: "John", targetChapterNumber: 6, targetVerse: 45, relationshipDescription: "Jesus quotes Isaiah's promise that all will be taught by God to explain that those who hear and learn from the Father come to him."),
        Entry(bookName: "Isaiah", chapterNumber: 55, sourceVerse: 3, targetBookName: "Acts", targetChapterNumber: 13, targetVerse: 34, relationshipDescription: "Paul identifies Jesus' resurrection as the fulfillment of Isaiah's sure mercies promised to David, the enduring covenant blessings that cannot decay."),
        Entry(bookName: "Isaiah", chapterNumber: 56, sourceVerse: 7, targetBookName: "Luke", targetChapterNumber: 19, targetVerse: 46, relationshipDescription: "Jesus quotes Isaiah's vision of a house of prayer when confronting those who turned the temple into a den of robbers."),
        Entry(bookName: "Isaiah", chapterNumber: 56, sourceVerse: 7, targetBookName: "Mark", targetChapterNumber: 11, targetVerse: 17, relationshipDescription: "Jesus quotes Isaiah's promise that the temple is a house of prayer for all nations while condemning its corruption."),
        Entry(bookName: "Isaiah", chapterNumber: 58, sourceVerse: 7, targetBookName: "Ezekiel", targetChapterNumber: 18, targetVerse: 7, relationshipDescription: "Ezekiel describes the righteous person sharing bread, clothing the naked, and helping the afflicted, concretely echoing Isaiah's call for the fast God chooses."),
        Entry(bookName: "Isaiah", chapterNumber: 58, sourceVerse: 7, targetBookName: "Ezekiel", targetChapterNumber: 18, targetVerse: 16, relationshipDescription: "Ezekiel repeats the acts of mercy Isaiah requires—feeding the hungry, clothing the naked, and avoiding oppression—as marks of the righteous life."),
        Entry(bookName: "Isaiah", chapterNumber: 58, sourceVerse: 14, targetBookName: "Deuteronomy", targetChapterNumber: 32, targetVerse: 13, relationshipDescription: "Isaiah applies Moses' image of riding the heights and enjoying the land's abundance to Sabbath faithfulness and the heritage promised to Jacob."),
        Entry(bookName: "Isaiah", chapterNumber: 59, sourceVerse: 7, targetBookName: "Romans", targetChapterNumber: 3, targetVerse: 15, relationshipDescription: "Paul quotes Isaiah's indictment of feet rushing to bloodshed to establish that both Jews and Gentiles stand under sin."),
        Entry(bookName: "Isaiah", chapterNumber: 60, sourceVerse: 6, targetBookName: "Psalms", targetChapterNumber: 72, targetVerse: 15, relationshipDescription: "Isaiah's vision of gold and frankincense from Sheba develops Psalm 72's prayer that tribute from Sheba honor the righteous king."),
        Entry(bookName: "Isaiah", chapterNumber: 60, sourceVerse: 6, targetBookName: "Genesis", targetChapterNumber: 25, targetVerse: 3, relationshipDescription: "Genesis names Midian and Ephah among Abraham's descendants through Keturah, identifying the peoples Isaiah envisions bringing gifts to Zion."),
        Entry(bookName: "Isaiah", chapterNumber: 60, sourceVerse: 7, targetBookName: "Genesis", targetChapterNumber: 25, targetVerse: 13, relationshipDescription: "Genesis identifies Kedar as Ishmael's son, the ancestral line of the flocks Isaiah foresees being accepted on the Lord's altar."),
        Entry(bookName: "Isaiah", chapterNumber: 60, sourceVerse: 9, targetBookName: "Isaiah", targetChapterNumber: 2, targetVerse: 16, relationshipDescription: "Isaiah contrasts ships of Tarshish humbled in the day of the Lord with ships of Tarshish later bringing Zion's children and wealth home."),
        Entry(bookName: "Isaiah", chapterNumber: 61, sourceVerse: 1, targetBookName: "Luke", targetChapterNumber: 4, targetVerse: 18, relationshipDescription: "Jesus reads Isaiah's Spirit-anointed proclamation of good news, release, and sight as the description of his own ministry."),
        Entry(bookName: "Isaiah", chapterNumber: 61, sourceVerse: 2, targetBookName: "Luke", targetChapterNumber: 4, targetVerse: 19, relationshipDescription: "Jesus' reading announces Isaiah's year of the Lord's favor as fulfilled in the hearing of the Nazareth synagogue."),
        Entry(bookName: "Isaiah", chapterNumber: 61, sourceVerse: 1, targetBookName: "Luke", targetChapterNumber: 4, targetVerse: 17, relationshipDescription: "Luke introduces Jesus reading Isaiah's servant proclamation in the synagogue before he declares that the Scripture is fulfilled in him."),
        Entry(bookName: "Isaiah", chapterNumber: 62, sourceVerse: 10, targetBookName: "Isaiah", targetChapterNumber: 40, targetVerse: 3, relationshipDescription: "Isaiah repeats the call to prepare a highway for the Lord's return, now directing Zion's people to clear a way for the redeemed to enter."),
        Entry(bookName: "Isaiah", chapterNumber: 63, sourceVerse: 1, targetBookName: "Psalms", targetChapterNumber: 137, targetVerse: 7, relationshipDescription: "Both invoke Edom in connection with divine judgment on Jerusalem's enemies; Isaiah's warrior from Bozrah answers the demand to remember Edom's violence."),
        Entry(bookName: "Isaiah", chapterNumber: 63, sourceVerse: 1, targetBookName: "Amos", targetChapterNumber: 1, targetVerse: 11, relationshipDescription: "Amos condemns Edom's relentless hostility and announces judgment on Teman and Bozrah, the same Edomite setting from which Isaiah's divine warrior comes."),
        Entry(bookName: "Isaiah", chapterNumber: 63, sourceVerse: 5, targetBookName: "Isaiah", targetChapterNumber: 59, targetVerse: 16, relationshipDescription: "Isaiah repeats the image of the Lord acting alone with his own arm to save and repay, developing it into the warrior's solitary execution of judgment."),
        Entry(bookName: "Isaiah", chapterNumber: 65, sourceVerse: 1, targetBookName: "Romans", targetChapterNumber: 10, targetVerse: 20, relationshipDescription: "Paul quotes Isaiah's declaration that God was found by those not seeking him to explain the Gentiles' reception of the gospel."),
        Entry(bookName: "Isaiah", chapterNumber: 65, sourceVerse: 2, targetBookName: "Romans", targetChapterNumber: 10, targetVerse: 21, relationshipDescription: "Paul quotes Isaiah's picture of God holding out his hands to a disobedient people to describe Israel's persistent refusal of the gospel."),
        Entry(bookName: "Isaiah", chapterNumber: 65, sourceVerse: 17, targetBookName: "Revelation", targetChapterNumber: 21, targetVerse: 1, relationshipDescription: "Revelation develops Isaiah's promise of new heavens and a new earth into the vision of the first creation passing away before God's final dwelling with humanity."),
        Entry(bookName: "Isaiah", chapterNumber: 66, sourceVerse: 1, targetBookName: "Acts", targetChapterNumber: 7, targetVerse: 49, relationshipDescription: "Stephen quotes Isaiah's declaration that heaven is God's throne and earth his footstool to challenge a temple-centered resistance to God's messengers."),
        Entry(bookName: "Isaiah", chapterNumber: 66, sourceVerse: 24, targetBookName: "Mark", targetChapterNumber: 9, targetVerse: 48, relationshipDescription: "Jesus applies Isaiah's image of the undying worm and unquenched fire to warn of Gehenna's final judgment.")
    ]

    private nonisolated static let entriesPart51: [Entry] = [
        Entry(bookName: "Jeremiah", chapterNumber: 1, sourceVerse: 8, targetBookName: "Jeremiah", targetChapterNumber: 15, targetVerse: 20, relationshipDescription: "The Lord repeats his commissioning assurance to Jeremiah: hostile opponents will fight him, but God will be with him to save and deliver him."),
        Entry(bookName: "Jeremiah", chapterNumber: 1, sourceVerse: 9, targetBookName: "Isaiah", targetChapterNumber: 51, targetVerse: 16, relationshipDescription: "Both prophets receive the Lord's words in their mouths for a divine mission; Isaiah's servant language broadens Jeremiah's commissioning pattern to Zion's restoration."),
        Entry(bookName: "Jeremiah", chapterNumber: 1, sourceVerse: 9, targetBookName: "Jeremiah", targetChapterNumber: 5, targetVerse: 14, relationshipDescription: "Jeremiah's commissioning to speak God's words is developed when the Lord makes those words a fire that consumes the disobedient people."),
        Entry(bookName: "Jeremiah", chapterNumber: 1, sourceVerse: 10, targetBookName: "Jeremiah", targetChapterNumber: 31, targetVerse: 28, relationshipDescription: "The sixfold commission to uproot and build becomes the Lord's promise to watch over Israel for restoration after watching over it for judgment."),
        Entry(bookName: "Jeremiah", chapterNumber: 1, sourceVerse: 10, targetBookName: "Jeremiah", targetChapterNumber: 18, targetVerse: 7, relationshipDescription: "Jeremiah 18 explains the commission to uproot or build nations through the potter's principle that a nation's response can alter the announced outcome."),
        Entry(bookName: "Jeremiah", chapterNumber: 1, sourceVerse: 16, targetBookName: "Jeremiah", targetChapterNumber: 19, targetVerse: 4, relationshipDescription: "Jeremiah 19 specifies the idolatry behind the judgment announced at his call: Judah has forsaken the Lord and filled the land with foreign worship."),
        Entry(bookName: "Jeremiah", chapterNumber: 1, sourceVerse: 16, targetBookName: "2 Kings", targetChapterNumber: 22, targetVerse: 17, relationshipDescription: "The judgment for making offerings to other gods announced in Jeremiah's call is the same covenant offense identified in Huldah's warning to Josiah."),
        Entry(bookName: "Jeremiah", chapterNumber: 1, sourceVerse: 16, targetBookName: "2 Chronicles", targetChapterNumber: 34, targetVerse: 25, relationshipDescription: "Chronicles preserves Huldah's warning that Judah's idolatry kindled the Lord's wrath, the judgment Jeremiah is commissioned to pronounce."),
        Entry(bookName: "Jeremiah", chapterNumber: 2, sourceVerse: 13, targetBookName: "Jeremiah", targetChapterNumber: 17, targetVerse: 13, relationshipDescription: "Jeremiah returns to the fountain image: abandoning the Lord, the fountain of living water, brings shame and is written in the dust."),
        Entry(bookName: "Jeremiah", chapterNumber: 2, sourceVerse: 16, targetBookName: "Jeremiah", targetChapterNumber: 46, targetVerse: 14, relationshipDescription: "Jeremiah's early warning that Memphis and Tahpanhes have wounded Judah is developed in the later Egyptian oracle that names those cities before Babylon's advance."),
        Entry(bookName: "Jeremiah", chapterNumber: 2, sourceVerse: 20, targetBookName: "Deuteronomy", targetChapterNumber: 12, targetVerse: 2, relationshipDescription: "Jeremiah's accusation of worship under every green tree exposes Judah doing what Deuteronomy commanded Israel to destroy in Canaanite worship."),
        Entry(bookName: "Jeremiah", chapterNumber: 2, sourceVerse: 20, targetBookName: "Jeremiah", targetChapterNumber: 3, targetVerse: 6, relationshipDescription: "Jeremiah identifies Israel's worship on every high hill and under every green tree as covenant adultery, developing the charge from chapter 2."),
        Entry(bookName: "Jeremiah", chapterNumber: 3, sourceVerse: 1, targetBookName: "Ezekiel", targetChapterNumber: 16, targetVerse: 28, relationshipDescription: "Ezekiel intensifies Jeremiah's marriage metaphor for Judah's unfaithfulness by portraying Jerusalem pursuing foreign lovers and alliances."),
        Entry(bookName: "Jeremiah", chapterNumber: 3, sourceVerse: 6, targetBookName: "1 Kings", targetChapterNumber: 14, targetVerse: 23, relationshipDescription: "Jeremiah's charge of worship on high places and under green trees recalls the cultic pattern recorded in Judah during Rehoboam's reign."),
        Entry(bookName: "Jeremiah", chapterNumber: 4, sourceVerse: 3, targetBookName: "Hosea", targetChapterNumber: 10, targetVerse: 12, relationshipDescription: "Hosea and Jeremiah use breaking fallow ground to call covenant people to renewed faithfulness rather than sowing among thorns or reaping injustice."),
        Entry(bookName: "Jeremiah", chapterNumber: 4, sourceVerse: 5, targetBookName: "Jeremiah", targetChapterNumber: 8, targetVerse: 14, relationshipDescription: "Jeremiah repeats the alarm to flee into fortified cities as the people's response to the northern disaster he announced earlier."),
        Entry(bookName: "Jeremiah", chapterNumber: 4, sourceVerse: 15, targetBookName: "Jeremiah", targetChapterNumber: 8, targetVerse: 16, relationshipDescription: "Jeremiah repeats the report from Dan and the sound of enemy horses, developing the northern invasion from warning into imminent devastation."),
        Entry(bookName: "Jeremiah", chapterNumber: 4, sourceVerse: 23, targetBookName: "Genesis", targetChapterNumber: 1, targetVerse: 2, relationshipDescription: "Jeremiah reverses Genesis' creation language—formless, empty, and dark—to portray Judah's coming judgment as an undoing of the created order."),
        Entry(bookName: "Jeremiah", chapterNumber: 6, sourceVerse: 13, targetBookName: "Jeremiah", targetChapterNumber: 8, targetVerse: 10, relationshipDescription: "Jeremiah repeats the indictment that everyone, including prophet and priest, is greedy for gain as he renews the case against Judah's leaders."),
        Entry(bookName: "Jeremiah", chapterNumber: 6, sourceVerse: 15, targetBookName: "Jeremiah", targetChapterNumber: 8, targetVerse: 12, relationshipDescription: "Jeremiah repeats that Judah feels no shame for its abominations, confirming that those who refuse to blush will fall under judgment."),
        Entry(bookName: "Jeremiah", chapterNumber: 7, sourceVerse: 11, targetBookName: "Luke", targetChapterNumber: 19, targetVerse: 46, relationshipDescription: "Jesus quotes Jeremiah's charge that the temple became a den of robbers when confronting those who corrupted its worship."),
        Entry(bookName: "Jeremiah", chapterNumber: 7, sourceVerse: 11, targetBookName: "Mark", targetChapterNumber: 11, targetVerse: 17, relationshipDescription: "Jesus uses Jeremiah's den-of-robbers accusation to condemn the temple's corruption while recalling its calling as a house of prayer."),
        Entry(bookName: "Jeremiah", chapterNumber: 8, sourceVerse: 2, targetBookName: "Deuteronomy", targetChapterNumber: 4, targetVerse: 19, relationshipDescription: "Jeremiah condemns Judah for serving the heavenly bodies, precisely the worship Deuteronomy warned Israel not to be drawn into."),
        Entry(bookName: "Jeremiah", chapterNumber: 8, sourceVerse: 3, targetBookName: "Jeremiah", targetChapterNumber: 29, targetVerse: 14, relationshipDescription: "Jeremiah's preference for death among the scattered is answered by the later promise that the Lord will gather the exiles from every place and restore them."),
        Entry(bookName: "Jeremiah", chapterNumber: 8, sourceVerse: 3, targetBookName: "Jeremiah", targetChapterNumber: 23, targetVerse: 3, relationshipDescription: "The scattered remnant left under judgment anticipates Jeremiah's promise that the Lord will gather the remnant from the countries where he drove them."),
        Entry(bookName: "Jeremiah", chapterNumber: 8, sourceVerse: 22, targetBookName: "Jeremiah", targetChapterNumber: 46, targetVerse: 11, relationshipDescription: "Jeremiah's question about balm in Gilead is answered bitterly in the Egyptian oracle: even abundant balm cannot heal Egypt's wound."),
        Entry(bookName: "Jeremiah", chapterNumber: 9, sourceVerse: 24, targetBookName: "1 Corinthians", targetChapterNumber: 1, targetVerse: 31, relationshipDescription: "Paul quotes Jeremiah's command to boast in the Lord to show that God's saving work leaves no room for human boasting."),
        Entry(bookName: "Jeremiah", chapterNumber: 9, sourceVerse: 24, targetBookName: "2 Corinthians", targetChapterNumber: 10, targetVerse: 17, relationshipDescription: "Paul repeats Jeremiah's command to boast in the Lord when measuring ministry by the Lord's commendation rather than self-praise."),
        Entry(bookName: "Jeremiah", chapterNumber: 10, sourceVerse: 14, targetBookName: "Jeremiah", targetChapterNumber: 51, targetVerse: 17, relationshipDescription: "Jeremiah repeats the verdict that every idol maker is foolish and every image a fraud in the oracle declaring Babylon's idols powerless."),
        Entry(bookName: "Jeremiah", chapterNumber: 10, sourceVerse: 15, targetBookName: "Jeremiah", targetChapterNumber: 51, targetVerse: 18, relationshipDescription: "Jeremiah repeats that idols are worthless works of mockery destined to perish when the Lord visits them in judgment."),
        Entry(bookName: "Jeremiah", chapterNumber: 10, sourceVerse: 16, targetBookName: "Jeremiah", targetChapterNumber: 51, targetVerse: 19, relationshipDescription: "Jeremiah repeats that the Lord, Jacob's portion and maker of all, is unlike the powerless idols condemned in Babylon."),
        Entry(bookName: "Jeremiah", chapterNumber: 10, sourceVerse: 22, targetBookName: "Jeremiah", targetChapterNumber: 9, targetVerse: 11, relationshipDescription: "Jeremiah's report of the northern invasion fulfills the warning that Jerusalem's cities will become a ruin and a haunt of jackals.")
    ]

    private nonisolated static let entriesPart52: [Entry] = [
        Entry(bookName: "Jeremiah", chapterNumber: 11, sourceVerse: 5, targetBookName: "Exodus", targetChapterNumber: 13, targetVerse: 5, relationshipDescription: "Jeremiah invokes the land flowing with milk and honey that the Lord swore to give Israel, the inheritance Exodus describes after the exodus."),
        Entry(bookName: "Jeremiah", chapterNumber: 11, sourceVerse: 5, targetBookName: "Exodus", targetChapterNumber: 3, targetVerse: 8, relationshipDescription: "Jeremiah grounds the covenant oath in the Lord's earlier promise to bring Israel from Egypt into the fertile land of Canaan."),
        Entry(bookName: "Jeremiah", chapterNumber: 11, sourceVerse: 5, targetBookName: "Genesis", targetChapterNumber: 26, targetVerse: 3, relationshipDescription: "The land oath Jeremiah recalls is part of the promise the Lord repeated to Isaac: Abraham's descendants would inherit the land through covenant faithfulness."),
        Entry(bookName: "Jeremiah", chapterNumber: 11, sourceVerse: 8, targetBookName: "Jeremiah", targetChapterNumber: 7, targetVerse: 24, relationshipDescription: "Jeremiah repeats that Israel's ancestors refused to listen and followed their stubborn evil hearts, explaining why the covenant curses came upon them."),
        Entry(bookName: "Jeremiah", chapterNumber: 11, sourceVerse: 8, targetBookName: "Jeremiah", targetChapterNumber: 7, targetVerse: 26, relationshipDescription: "Jeremiah's indictment of refusing to listen continues the charge that Israel's fathers stiffened their necks and became worse than their ancestors."),
        Entry(bookName: "Jeremiah", chapterNumber: 11, sourceVerse: 14, targetBookName: "Jeremiah", targetChapterNumber: 7, targetVerse: 16, relationshipDescription: "The Lord repeats his command that Jeremiah not intercede for this people because their persistent evil has brought a judgment no prayer will avert."),
        Entry(bookName: "Jeremiah", chapterNumber: 11, sourceVerse: 16, targetBookName: "Psalms", targetChapterNumber: 52, targetVerse: 8, relationshipDescription: "Jeremiah turns the flourishing olive-tree image of the righteous into a judgment image for Judah, whose once-beautiful tree will be set ablaze for evil."),
        Entry(bookName: "Jeremiah", chapterNumber: 11, sourceVerse: 20, targetBookName: "Jeremiah", targetChapterNumber: 20, targetVerse: 12, relationshipDescription: "Jeremiah again entrusts his case to the Lord who tests the righteous and examines heart and mind, asking to see God's vindication against his persecutors."),
        Entry(bookName: "Jeremiah", chapterNumber: 14, sourceVerse: 10, targetBookName: "Hosea", targetChapterNumber: 8, targetVerse: 13, relationshipDescription: "Hosea and Jeremiah announce that the Lord remembers Israel's iniquity and punishes its sins because its worship has become rebellion rather than covenant faithfulness."),
        Entry(bookName: "Jeremiah", chapterNumber: 15, sourceVerse: 2, targetBookName: "Jeremiah", targetChapterNumber: 43, targetVerse: 11, relationshipDescription: "Jeremiah repeats the appointed fates of death, sword, famine, and captivity when announcing Babylon's judgment on those who flee to Egypt."),
        Entry(bookName: "Jeremiah", chapterNumber: 17, sourceVerse: 4, targetBookName: "Jeremiah", targetChapterNumber: 15, targetVerse: 14, relationshipDescription: "The Lord's warning that Judah will serve enemies in an unknown land is repeated in the personal judgment language of Jeremiah 15, where his adversaries are given power over him."),
        Entry(bookName: "Jeremiah", chapterNumber: 17, sourceVerse: 10, targetBookName: "Jeremiah", targetChapterNumber: 32, targetVerse: 19, relationshipDescription: "Jeremiah repeats that the Lord searches the heart and repays each person according to conduct, praising the wisdom of his judgment over every human way."),
        Entry(bookName: "Jeremiah", chapterNumber: 17, sourceVerse: 10, targetBookName: "Jeremiah", targetChapterNumber: 21, targetVerse: 14, relationshipDescription: "Jeremiah applies the Lord's judgment according to each person's ways to Jerusalem, promising that its actions will bring a fire no surrounding forest can escape."),
        Entry(bookName: "Jeremiah", chapterNumber: 17, sourceVerse: 25, targetBookName: "Jeremiah", targetChapterNumber: 22, targetVerse: 4, relationshipDescription: "Jeremiah repeats the promise that Davidic kings and their officials will enter Jerusalem's gates if they obey the Lord's covenant command."),
        Entry(bookName: "Jeremiah", chapterNumber: 17, sourceVerse: 25, targetBookName: "Jeremiah", targetChapterNumber: 22, targetVerse: 30, relationshipDescription: "The conditional promise of a Davidic ruler entering Jerusalem's gates is set against the later judgment that Jeconiah will have no descendant ruling on David's throne."),
        Entry(bookName: "Jeremiah", chapterNumber: 18, sourceVerse: 9, targetBookName: "Jeremiah", targetChapterNumber: 31, targetVerse: 28, relationshipDescription: "Jeremiah repeats the Lord's purpose to build and plant, turning the potter's warning about nations into the restoration promise for Israel after judgment."),
        Entry(bookName: "Jeremiah", chapterNumber: 18, sourceVerse: 9, targetBookName: "Jeremiah", targetChapterNumber: 1, targetVerse: 10, relationshipDescription: "Jeremiah explains the commissioning language of building and planting through the Lord's freedom to announce restoration for a nation after warning it of judgment."),
        Entry(bookName: "Jeremiah", chapterNumber: 18, sourceVerse: 11, targetBookName: "Jeremiah", targetChapterNumber: 7, targetVerse: 3, relationshipDescription: "Jeremiah repeats the call to amend ways and deeds so that the Lord may let Judah remain in the land rather than bring the disaster it has chosen."),
        Entry(bookName: "Jeremiah", chapterNumber: 18, sourceVerse: 11, targetBookName: "Jeremiah", targetChapterNumber: 26, targetVerse: 13, relationshipDescription: "Jeremiah restates his call for Judah to amend its ways and obey the Lord, holding out the possibility that the announced disaster may be relented of."),
        Entry(bookName: "Jeremiah", chapterNumber: 18, sourceVerse: 16, targetBookName: "Jeremiah", targetChapterNumber: 19, targetVerse: 8, relationshipDescription: "Jeremiah's warning that Judah will become an object of horror is repeated after the broken jar sign, confirming the permanent devastation their idolatry brings."),
        Entry(bookName: "Jeremiah", chapterNumber: 19, sourceVerse: 5, targetBookName: "Jeremiah", targetChapterNumber: 32, targetVerse: 35, relationshipDescription: "Jeremiah identifies Judah's child sacrifices to Baal as the abomination later specified in the charge that they made sons and daughters pass through fire to Molech."),
        Entry(bookName: "Jeremiah", chapterNumber: 19, sourceVerse: 6, targetBookName: "Jeremiah", targetChapterNumber: 7, targetVerse: 32, relationshipDescription: "Jeremiah repeats the warning that the Valley of Ben Hinnom will become the Valley of Slaughter, filled with corpses for birds and beasts."),
        Entry(bookName: "Jeremiah", chapterNumber: 19, sourceVerse: 13, targetBookName: "Jeremiah", targetChapterNumber: 32, targetVerse: 29, relationshipDescription: "Jeremiah repeats the indictment of rooftops used to burn incense to Baal, identifying the idolatry that makes Jerusalem's houses defiled like Topheth."),
        Entry(bookName: "Jeremiah", chapterNumber: 20, sourceVerse: 1, targetBookName: "Ezra", targetChapterNumber: 2, targetVerse: 37, relationshipDescription: "Ezra lists the descendants of Pashhur among the returning priests, preserving the priestly family of the temple official who opposed Jeremiah."),
        Entry(bookName: "Jeremiah", chapterNumber: 20, sourceVerse: 1, targetBookName: "1 Chronicles", targetChapterNumber: 24, targetVerse: 14, relationshipDescription: "Pashhur is identified as a son of Immer; Chronicles records Immer's priestly division, locating Jeremiah's opponent within that temple family line."),
        Entry(bookName: "Jeremiah", chapterNumber: 21, sourceVerse: 1, targetBookName: "Jeremiah", targetChapterNumber: 37, targetVerse: 3, relationshipDescription: "During Babylon's siege, Zedekiah again sends a delegation to Jeremiah asking him to seek the Lord, showing the king's repeated but unrepentant appeal for help."),
        Entry(bookName: "Jeremiah", chapterNumber: 21, sourceVerse: 1, targetBookName: "Jeremiah", targetChapterNumber: 29, targetVerse: 25, relationshipDescription: "Zephaniah son of Maaseiah, who accompanies Zedekiah's request to Jeremiah, also receives Jeremiah's correspondence concerning the Jerusalem priesthood."),
        Entry(bookName: "Jeremiah", chapterNumber: 21, sourceVerse: 1, targetBookName: "Jeremiah", targetChapterNumber: 52, targetVerse: 24, relationshipDescription: "Zephaniah the second priest, who carries Zedekiah's request, is later seized and executed after Jerusalem falls, tracing the priest's role through the final crisis."),
